impl miniserde::de::Visitor for Place<StructType> {
    fn string(&mut self, s: &str) -> miniserde::Result<()> {
        self.out = StructType::from_str(s);
        if self.out.is_some() { Ok(()) } else { Err(miniserde::Error) }
    }
}

